import{_ as t,o as i,c as o,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"Staging Hotfixes & UI Polish Test Plan","description":"","frontmatter":{},"headers":[],"relativePath":"testing/staging-hotfixes-test-plan.md","filePath":"testing/staging-hotfixes-test-plan.md"}'),s={name:"testing/staging-hotfixes-test-plan.md"};function n(r,e,l,u,h,g){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="staging-hotfixes-ui-polish-test-plan" tabindex="-1">Staging Hotfixes &amp; UI Polish Test Plan <a class="header-anchor" href="#staging-hotfixes-ui-polish-test-plan" aria-label="Permalink to &quot;Staging Hotfixes &amp; UI Polish Test Plan&quot;">​</a></h1><p>This test plan covers the validation of the 6 staging hotfixes and UI improvements.</p><h2 id="_1-automation-image-auth-fix" tabindex="-1">1. Automation Image Auth Fix <a class="header-anchor" href="#_1-automation-image-auth-fix" aria-label="Permalink to &quot;1. Automation Image Auth Fix&quot;">​</a></h2><p><strong>Description:</strong> Fixes the &quot;Authentication is not set up&quot; error occurring during automated image generation. <strong>Test Steps:</strong></p><ol><li>Log in as an authenticated user.</li><li>Open a project and navigate to the automation or image generation section.</li><li>Trigger an automated image generation.</li><li><strong>Expected Result:</strong> The image generation completes successfully without throwing an &quot;Authentication is not set up&quot; error.</li></ol><h2 id="_2-youtube-token-refresh-fix" tabindex="-1">2. YouTube Token Refresh Fix <a class="header-anchor" href="#_2-youtube-token-refresh-fix" aria-label="Permalink to &quot;2. YouTube Token Refresh Fix&quot;">​</a></h2><p><strong>Description:</strong> Fixes the offline token refresh failing in staging background workers. <strong>Test Steps:</strong></p><ol><li>Connect a YouTube account.</li><li>Ensure the access token has expired (or simulate expiry).</li><li>Trigger a background worker task that requires YouTube API access (e.g., publishing a video).</li><li><strong>Expected Result:</strong> The background worker successfully refreshes the token and completes the task without authorization errors.</li></ol><h2 id="_3-state-persistence-via-url" tabindex="-1">3. State Persistence via URL <a class="header-anchor" href="#_3-state-persistence-via-url" aria-label="Permalink to &quot;3. State Persistence via URL&quot;">​</a></h2><p><strong>Description:</strong> Persists the active project/script state in the URL to prevent redirects to the home page on refresh. <strong>Test Steps:</strong></p><ol><li>Open a specific project and script in the Studio.</li><li>Note the URL includes the project and script identifiers.</li><li>Refresh the browser page.</li><li><strong>Expected Result:</strong> The application reloads exactly where the user left off, without redirecting to the home dashboard.</li></ol><h2 id="_4-mobile-ui-fix-script-name-bar-cutoff" tabindex="-1">4. Mobile UI Fix (Script Name Bar Cutoff) <a class="header-anchor" href="#_4-mobile-ui-fix-script-name-bar-cutoff" aria-label="Permalink to &quot;4. Mobile UI Fix (Script Name Bar Cutoff)&quot;">​</a></h2><p><strong>Description:</strong> Fixes the script name bar cutoff issue on mobile devices. <strong>Test Steps:</strong></p><ol><li>Open the Studio application on a mobile device or a simulated mobile viewport.</li><li>Navigate to a script with a long name.</li><li>Observe the script name bar at the top of the screen.</li><li><strong>Expected Result:</strong> The script name is fully visible, properly truncated with ellipses if necessary, and does not overlap or get cut off by screen boundaries.</li></ol><h2 id="_5-automation-modal-text-polish" tabindex="-1">5. Automation Modal Text Polish <a class="header-anchor" href="#_5-automation-modal-text-polish" aria-label="Permalink to &quot;5. Automation Modal Text Polish&quot;">​</a></h2><p><strong>Description:</strong> Updates and polishes the text within the Automation Modal. <strong>Test Steps:</strong></p><ol><li>Trigger the Automation Modal.</li><li>Review the text instructions and labels.</li><li><strong>Expected Result:</strong> The text reflects the new, polished copy without typos or formatting errors.</li></ol><h2 id="_6-missing-generate-all-images-menu-button" tabindex="-1">6. Missing &quot;Generate All Images&quot; Menu Button <a class="header-anchor" href="#_6-missing-generate-all-images-menu-button" aria-label="Permalink to &quot;6. Missing &quot;Generate All Images&quot; Menu Button&quot;">​</a></h2><p><strong>Description:</strong> Restores the missing &quot;Generate All Images&quot; button in the menu. <strong>Test Steps:</strong></p><ol><li>Open the Studio and navigate to the image generation or assets menu.</li><li>Locate the menu options.</li><li><strong>Expected Result:</strong> The &quot;Generate All Images&quot; button is present and clickable. Clicking it should trigger the batch image generation process.</li></ol>',20)])])}const d=t(s,[["render",n]]);export{p as __pageData,d as default};
